13	import { PARENT_ISSUE_TAG } from "../../adapters/github/tags.ts";
14	import { defineScript } from "./lib/script-ref.ts";
15	
16	export const ref = defineScript(import.meta.url);
17	
18	function main(): void {
19	  const body = process.env.PR_BODY ?? "";
20	  const prNumber = process.env.PR_NUMBER ?? "";
21	  const githubOutput = process.env.GITHUB_OUTPUT;
22	
23	  // Kept as a string: it is written straight to $GITHUB_OUTPUT, and an absent
24	  // tag has to render as empty so the caller's `if: ... != ''` stays false.
25	  const parentIssue = PARENT_ISSUE_TAG.read(body);
26	  const parent = parentIssue === undefined ? "" : String(parentIssue);
27	  if (parent) console.error(`PR #${prNumber} belongs to issue #${parent}`);
28	  else console.error(`PR #${prNumber} has no parent-issue metadata`);
29	
30	  // One output, where there used to be two.
31	  //
32	  // `sub_number` was `closedIssueNumber(body)` and `parent_number` was this tag —
33	  // and the two were the SAME NUMBER every time, because `injectParentIssue` wrote
34	  // both from the run's one issue number. The only consumer fed `sub_number` to
35	  // `parentIssueOf` to find the issue's own parent, so which of the two it was
36	  // handed made no difference.
37	  //
38	  // Both halves of the old pair are gone with it: the `Closes` line no longer
39	  // exists to be read (#171), and a second spelling of one number is the shape
40	  // this repository keeps removing. See `issue-links.ts`'s `partOfLine`.
41	  if (githubOutput) appendFileSync(githubOutput, `parent_number=${parent}\n`);
42	}
